  const DBL2 = [["begin","ing","beginning","d"],["forget","ing","forgetting","d"],["admit","ed","admitted","d"],["prefer","ed","preferred","d"],["occur","ed","occurred","d"],["control","ed","controlled","d"],["regret","ed","regretted","d"],["submit","ing","submitting","d"],["refer","ing","referring","d"],["permit","ed","permitted","d"],["equip","ed","equipped","d"],["upset","ing","upsetting","d"],["visit","ed","visited","n"],["open","ing","opening","n"],["listen","ed","listened","n"],["offer","ing","offering","n"],["happen","ed","happened","n"],["enter","ed","entered","n"],["gather","ed","gathered","n"],["answer","ing","answering","n"],["limit","ed","limited","n"]];
