  const YNESS = [["happy","ness","happiness"],["lonely","ness","loneliness"],["silly","ness","silliness"],["lazy","ness","laziness"],["ready","ness","readiness"],["empty","ness","emptiness"],["friendly","ness","friendliness"],["beauty","ful","beautiful"],["plenty","ful","plentiful"],["mercy","ful","merciful"],["pity","ful","pitiful"],["duty","ful","dutiful"]].map(([a, s, r]) => [`Add <b>-${s}</b> to <b>${a}</b>.`, r]);
