  const PREF3 = [["de-","decode","undo or remove","Think of the opposite of encode."],["de-","defrost","undo or remove","Think of what happens to ice in a freezer when you do this."],["co-","cooperate","together","Think of a team working on one job."],["co-","coauthor","together","Think of two writers on one book."],["ex-","export","out of","A ship carries goods this way from a country to others."],["ex-","exhale","out of","Think of breathing, and the opposite of inhale."],["pro-","progress","forward","A hiker who is doing this keeps going on the trail."],["pro-","propel","forward","A propeller does this to a boat or a plane."],["en-","enlarge","make or cause to be","A copy machine can do this to a photo."],["en-","enrich","make or cause to be","Adding vitamins to cereal does this to it."],["counter-","counterclockwise","against","Think about turning the knob the way the clock hands do NOT go."],["counter-","counteract","against","A medicine can do this to a poison."]];
