  const GREEK2 = [["automatic","auto","self","A door that opens as you walk up needs no push."],["bicycle","cycl","circle","Its wheels go round and round."],["polygon","poly","many","A pentagon and a hexagon are both this kind of shape."],["monotone","mono","one","A voice that never changes how high or low it is sounds like this."],["hemisphere","hemi","half","The northern part of the Earth is one of these."],["claustrophobia","phobia","fear","People with it may not like small, closed spaces."],["atmosphere","sphere","ball","Think about the shape of the Earth."],["sympathy","path","feeling","You show it when a friend is sad and you care."]];
  const HOMO7 = [["I ate a juicy ___.","pear",["pair","pare"]],["I bought a ___ of socks.","pair",["pear","pare"]],["The ___ comes in at the beach.","tide",["tied"]],["I ___ my shoes.","tied",["tide"]],["Walk down the ___ to find your seat.","aisle",["isle"]],["A small ___ in the sea has palm trees.","isle",["aisle"]],["I woke up early this ___.","morning",["mourning"]],["He flew in a small ___.","plane",["plain"]],["The land was flat and ___.","plain",["plane"]],["A knife can be made of ___.","steel",["steal"]],["It is wrong to ___ from others.","steal",["steel"]],["She plays the ___ of a pirate in the show.","role",["roll"]],["I ate a warm ___ with butter.","roll",["role"]],["Do not ___ water.","waste",["waist"]],["The belt goes around your ___.","waist",["waste"]],["Grandpa told a fairy ___.","tale",["tail"]],["The dog wagged its ___.","tail",["tale"]],["The queen's ___ lasted fifty years.","reign",["rain","rein"]],["Pull the ___ to stop the horse.","rein",["rain","reign"]],["The ___ fell all night.","rain",["reign","rein"]],["The shop will ___ old books.","sell",["cell"]],["Each ___ in your body is tiny.","cell",["sell"]],["The hotel gave us a big ___.","suite",["sweet"]],["The candy is very ___.","sweet",["suite"]]];
  const ISE = [["realize","","ize"],["organize","","ize"],["recognize","","ize"],["memorize","🧠","ize"],["apologize","","ize"],["summarize","","ize"],["criticize","","ize"],["advertise","📢","ise"],["advise","","ise"],["exercise","🏃","ise"],["surprise","🎁","ise"],["promise","🤞","ise"],["disguise","🥸","ise"],["compromise","🤝","ise"],["revise","✏️","ise"],["supervise","","ise"]];
  const SIL3 = [["wrap","w"],["wreck","w"],["doubt","b"],["debt","b"],["receipt","p"],["rhyme","h"],["plumber","b"],["subtle","b"],["gnome","g"],["limb","b"],["wrinkle","w"],["climb","b"],["thumb","b"]];
  const SYN5 = [["brave","courageous",["careless","selfish"]],["honest","truthful",["clever","jealous"]],["shy","timid",["bossy","noisy"]],["reluctant","hesitant",["eager","tidy"]],["ruin","destroy",["repair","borrow"]],["difficult","challenging",["simple","cheerful"]],["fix","repair",["break","sell"]],["huge","gigantic",["tiny","fragile"]],["unusual","rare",["common","careful"]],["sure","certain",["doubtful","hungry"]],["keen","eager",["bored","tall"]],["tidy","neat",["messy","loud"]],["rapid","swift",["slow","heavy"]],["gift","present",["trade","burden"]]].map(([a, b, d]) => [`Which word means almost the same as <b>${a}</b>?`, b, d]);
