  const TWOM = [["bank","We sat on the bank of the river and watched the ducks.","the land beside a river",["a place that keeps money","a long bench"]],["bank","Mom put the money in the bank.","a place that keeps money",["the land beside a river","a long bench"]],["light","The bag is so light that I can lift it with one finger.","not heavy",["a lamp's glow","pale in color"]],["light","Turn on the light so I can read.","a lamp's glow",["not heavy","pale in color"]],["bat","The bat flew out of the cave at night.","a small flying animal",["a stick for hitting a ball","a kind of bird's nest"]],["bat","He swung the bat and hit the ball.","a stick for hitting a ball",["a small flying animal","to blink quickly"]],["spring","Flowers bloom in the spring.","the season after winter",["a coil of metal","to jump up"]],["spring","The old mattress had a broken spring.","a coil of metal",["the season after winter","to jump up"]],["match","She lit the candle with a match.","a small stick that makes fire",["a contest between teams","two things that go together"]],["match","Our team won the soccer match.","a contest between teams",["a small stick that makes fire","a tool for digging"]],["well","We pulled water up from the well.","a deep hole with water in it",["in a good way","healthy"]],["well","She played the piano very well.","in a good way",["a deep hole with water in it","a kind of bucket"]],["fair","It is not fair to cheat.","treating everyone the same",["a place with rides and games","light in color"]],["fair","We rode the big wheel at the fair.","a place with rides and games",["treating everyone the same","a kind of fruit"]],["row","We sat in the front row.","a line of seats",["to paddle a boat","a noisy argument"]],["row","Please row the boat to the dock.","to paddle a boat",["a line of seats","a noisy argument"]]].map(([w, s, m, d]) => [`Read: <i>"${s}"</i><br>What does <b>${w}</b> mean here?`, m, d]);
  const SIMILE = [["quiet","mouse",["drum","lion"],"a"],["busy","bee",["rock","cloud"],"a"],["light","feather",["brick","bear"],"a"],["sly","fox",["cow","sheep"],"a"],["strong","ox",["daisy","feather"],"an"],["cold","ice",["soup","sun"],""],["blind","bat",["eagle","hawk"],"a"],["brave","lion",["mouse","rabbit"],"a"],["proud","peacock",["ant","worm"],"a"],["gentle","lamb",["tiger","wolf"],"a"],["clear","crystal",["mud","smoke"],""],["flat","pancake",["mountain","ball"],"a"],["sweet","honey",["lemon","salt"],""],["stubborn","mule",["feather","kitten"],"a"],["wise","owl",["hen","goldfish"],"an"]].map(([adj, a, d, art]) => [`Finish the simile:<br><b>as ${adj} as ${art ? art + " " : ""}___</b>`, a, d]);
