  const CONTR = [["could not","couldn't"],["should not","shouldn't"],["would not","wouldn't"],["does not","doesn't"],["had not","hadn't"],["they are","they're"],["we have","we've"],["they will","they'll"],["you are","you're"],["should have","should've"],["will not","won't"],["cannot","can't"],["who is","who's"],["that is","that's"],["has not","hasn't"],["I am","I'm"]].map(([a, b]) => [`Write <b>${a}</b> as one word with an apostrophe.`, b]);
